import { OneHandedPlaySetting } from '@game-studio/cabinet';
import { UserPreferenceValue, UserPreferences as UserPrefs } from '@game-studio/settings';

import { gameConfig } from './config-model';
import { inversifyContainer } from '../inversify/container';
import { eventEmitter } from '../services/event-emitter';
import { ChatSizeOption, userPref } from '../types';
import { chatColoursBackup } from '../views/settings-menu/chat-colours';
import { isInternationalBuild } from '../services/utilities';
import { queryStringParams } from '../services/query-string';
import { useCompanionState } from './companion-state';

interface IOpenUserPrefs {
    [key: string]: userPref;
}

class UserPreferences {
    public static get Instance(): UserPreferences { return this._instance || (this._instance = new UserPreferences()); }
    private static _instance: UserPreferences;

    private get companionState() { return useCompanionState(); }

    private constructor() { }

    public async initShellPreferences(): Promise<void> {
        // temp method to make sure we grab prefs from the shell until we swap over
        if (!isInternationalBuild()) {
            return;
        }
        // TODO: add this block back in for the legacy international shell
        // const internationalPrefs = await (inversifyContainer.frameConnection as unknown as ShellConnection<InternationalShellMeta>).methods.getUserPreferences(inversifyContainer.userPrefsGameName, {});
        // this.chatColour = internationalPrefs.preferences.chatcolour as number;
        // this.chatSize = internationalPrefs.preferences.chatsize as number;
        // this.sound = internationalPrefs.preferences.sound as boolean;
        // this.music = gameConfig.features.seperateMusicSoundControls ? internationalPrefs.preferences.music as boolean : this.sound;
        // if (internationalPrefs.preferences.colourBlindMode) {
        //     this.colourBlindMode = internationalPrefs.preferences.colourBlindMode as boolean;
        // }
        // this.oneHandedPlay = internationalPrefs.preferences.oneHandedPlay as OneHandedPlaySetting;
        // this.notifications = internationalPrefs.preferences.notifications as boolean;
    }

    // SOUND
    public get sound(): boolean {
        return UserPrefs.getPreference('sound', true, false, false);
    }

    public set sound(val: boolean) {
        UserPrefs.setPreference('sound', val, false, false, queryStringParams.isSubGame);
    }

    // MUSIC
    public get music(): boolean {
        return UserPrefs.getPreference('music', true, false, false);
    }

    public set music(val: boolean) {
        UserPrefs.setPreference('music', val, false, false, queryStringParams.isSubGame);
    }

    // CHATSIZE
    public get chatSize(): ChatSizeOption {
        return UserPrefs.getPreference('chatsize', 'medium', false, true);
    }

    public set chatSize(val: ChatSizeOption) {
        const chatSize = val;
        UserPrefs.setPreference('chatsize', chatSize, false, true);
    }

    // CHATCOLOUR
    public get chatColour(): string {
        return UserPrefs.getPreference('chatcolour', '#1E1E1E', false, true);
    }

    public set chatColour(val: string | number) {
        const colours = this.companionState.chatColours.value.length > 0 ? this.companionState.chatColours.value : chatColoursBackup;
        colours.forEach((chatColour, index) => {
            if (index === val || chatColour.value === val) {
                UserPrefs.setPreference('chatcolour', chatColour.value, false, true);
            }
        });
    }

    // NOTIFICATIONS
    public get notifications(): boolean {
        return UserPrefs.getPreference('notifications', true, false, true);
    }

    public set notifications(val: boolean) {
        UserPrefs.setPreference('notifications', val, false, true);
    }

    // ONEHANDEDPLAY
    public get oneHandedPlay(): number {
        return UserPrefs.getPreference('oneHandedPlay', OneHandedPlaySetting.right, false, true);
    }

    public set oneHandedPlay(val: OneHandedPlaySetting) {
        UserPrefs.setPreference('oneHandedPlay', val, false, true);
    }

    // COLOURBLIND
    public get colourBlindMode(): boolean {
        return UserPrefs.getPreference('colourBlindMode', false, false, true);
    }

    public set colourBlindMode(val: boolean) {
        UserPrefs.getPreference('colourBlindMode', false, false, true);
    }

    // Returns itself but typed with an index signature so props can be accessed with []
    private get openUserPrefs(): IOpenUserPrefs {
        return this as unknown as IOpenUserPrefs;
    }

    public setPreference(key: string, value: UserPreferenceValue & userPref, misc: boolean, global: boolean): void {
        UserPrefs.setPreference(key, value, misc, global);
        this.update({ [key]: value });
    }

    /**
     * Updates the Core User Preferences with the values passed
     * @param partial object containing the userPrefs you want to update
     */
    // public update(partial: Partial<IShellUserPreferencesEx>): void {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    public update(partial: any): void {
        // International Shell
        // const connection = (inversifyContainer.frameConnection as unknown as ShellConnection<ArcadeShellMeta>);
        // connection.methods.setUserPreferences({ gameName: inversifyContainer.userPrefsGameName, preferences: partial as InternationalTypes.IGamePreferences });

        if (partial.sound !== undefined) {
            this.sound = partial.sound;
            inversifyContainer.soundManager.sfx.muted = !this.sound;
        }

        if (partial.music !== undefined) {
            this.music = partial.music;
            inversifyContainer.soundManager.music.muted = !this.music;
        }

        if (partial.chatsize !== undefined) {
            this.chatSize = partial.chatsize;
        }

        if (partial.chatcolour !== undefined) {
            const colours = this.companionState.chatColours.value.length > 0 ? this.companionState.chatColours.value : chatColoursBackup;
            this.chatColour = colours[partial.chatcolour].value;
        }

        if (partial.notifications !== undefined) {
            this.notifications = partial.notifications;
        }

        if (partial.oneHandedPlay !== undefined) {
            this.oneHandedPlay = partial.oneHandedPlay;
        }

        if (partial.colourBlindMode !== undefined) {
            if (this.colourBlindMode !== partial.colourBlindMode) {
                this.colourBlindMode = partial.colourBlindMode;
            }
        }

        // Update any valid gamePrefs present in the partial
        for (const key in gameConfig.gamePrefs) {
            if (gameConfig.gamePrefs[key] !== undefined) {
                const newValue = partial[key];
                if (newValue !== undefined) {
                    if (typeof newValue !== typeof this.openUserPrefs[key]) { console.error(`In userPrefs.update(). Attempted to change type of gamePref ${key} from ${typeof this.openUserPrefs[key]} to ${typeof newValue}. Value has not been updated.`); return; }

                    // Only want to update preference or send events if the value has changed
                    if (this.openUserPrefs[key] !== newValue) {
                        this.openUserPrefs[key] = newValue;

                        // If the gamePref has a linked event, emit that with it's new value
                        // const event = gameConfig.gamePrefs[key].event;
                        const eventName = gameConfig.gamePrefs[key].eventName;
                        // if (event) {
                        //     event.dispatch(newValue);
                        // } else if (eventName) {
                        //     // eslint-disable-next-line
                        //     eventEmitter.emit(eventName as any, newValue);
                        // }
                        // eslint-disable-next-line @typescript-eslint/no-explicit-any
                        eventEmitter.emit(eventName as any, newValue);
                    }
                }
            }
        }
    }

    /** Called by the engine to add the preferences defined in the gameConfig */
    public initialiseGamePreferences(): void {
        for (const key in gameConfig.gamePrefs) {
            if (gameConfig.gamePrefs[key] !== undefined) {
                this.openUserPrefs[key] = gameConfig.gamePrefs[key].default;
            }
        }
    }

    /**
     * Updates the named gamePref with the new value.
     * Prints an error if either there is no preference defined matching the passed name
     * or attempting to mutate the type, e.g. changing true to 'true'
     * @param name name of the pref to update
     * @param newValue new value to apply
     */
    public updateGamePref<T extends string>(name: T, newValue: userPref): void {
        if (gameConfig.gamePrefs[name] === undefined) { console.error(`No game pref of name: ${name} exists to update. Has it been passed to the BasePackage via it's config?`); return; }

        // const valueToUpdate: Partial<IShellUserPreferencesEx> = {};
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const valueToUpdate: any = {};
        valueToUpdate[name] = newValue;
        UserPrefs.setPreference(name, newValue, false, false);
    }

    /**
   * Returns an object containing each gamePref as a property with its value
   */
    public get gamePrefValues(): Record<string, unknown> {
        const values: Record<string, unknown> = {};
        for (const key in gameConfig.gamePrefs) {
            if (this.openUserPrefs[key]) {
                values[key] = this.openUserPrefs[key];
            }
        }
        return values;
    }

    /**
     * Returns the requested pref value
     * @param name name of the pref you want to access
     */
    public getGamePref<T extends string, R extends userPref>(name: T): R {
        if (gameConfig.gamePrefs[name].default === undefined) { console.error(`No user pref of name: ${name} exists. Has it been passed to the BasePackage via it's config?`); }
        const pref = UserPrefs.getPreference(name, gameConfig.gamePrefs[name].default, false, false);
        return pref as R;
    }
}

export type { UserPreferences };
export const userPreferences = UserPreferences.Instance;
